import json
import sys
import uuid

def translate():
    with open(sys.argv[1], 'r', encoding='utf-8') as f, open(sys.argv[2], 'w', encoding='utf-8') as out:
        out.write('{\"sessionId\": \"' + str(uuid.uuid4()) + '\"}\n')
        for line in f:
            if not line.strip(): continue
            try:
                rec = json.loads(line)
            except:
                continue

            if rec.get('type') == 'USER_INPUT':
                cc = {'type': 'message', 'message': {'role': 'user', 'content': [{'type': 'text', 'text': rec.get('content', '')}]}}
                out.write(json.dumps(cc) + '\n')

            elif rec.get('type') == 'PLANNER_RESPONSE':
                content = [{'type': 'text', 'text': rec.get('content', '')}]
                for tc in rec.get('tool_calls', []):
                    name = tc.get('name')
                    args = tc.get('args', {})
                    tc_id = tc.get('id', str(uuid.uuid4()))

                    cc_name = name
                    cc_input = args

                    if name == 'run_command':
                        cc_name = 'Bash'
                        cc_input = {'command': args.get('CommandLine', '')}
                    elif name == 'view_file':
                        cc_name = 'View'
                        cc_input = {'file_path': args.get('AbsolutePath', '')}
                    elif name == 'grep_search':
                        cc_name = 'Grep'
                        cc_input = {'pattern': args.get('Query', ''), 'path': args.get('SearchPath', '')}
                    elif name == 'write_to_file':
                        cc_name = 'Edit'
                        cc_input = {'file_path': args.get('TargetFile', ''), 'file_text': args.get('CodeContent', '')}
                    elif name == 'replace_file_content' or name == 'multi_replace_file_content':
                        cc_name = 'Replace'
                        cc_input = {'file_path': args.get('TargetFile', ''), 'replace': '...'}

                    content.append({'type': 'tool_use', 'id': tc_id, 'name': cc_name, 'input': cc_input})

                cc = {'type': 'message', 'message': {'role': 'assistant', 'content': content}}
                out.write(json.dumps(cc) + '\n')

            elif rec.get('type') == 'TOOL_RESPONSE':
                cc = {'type': 'message', 'message': {'role': 'user', 'content': [{'type': 'tool_result', 'tool_use_id': rec.get('tool_call_id', 'unknown'), 'content': [{'type': 'text', 'text': rec.get('content', '')}], 'is_error': False}]}}
                out.write(json.dumps(cc) + '\n')

translate()
